use kairos_execution_contract::ExecutionEvent;
use kairos_execution_contract::event::decode_event;

const FIXTURE: &str = "";

fn main() {
    let payload = decode_hex(FIXTURE);
    let event = decode_event(&payload).unwrap();
    let ExecutionEvent::IntentLifecycleChanged(root) = event else {
        panic!("fixture is not an intent lifecycle event");
    };
    assert_eq!(root.metadata().sequence(), 2);
    assert_eq!(root.intent().intent_id(), "intent-1");
    print!("{FIXTURE}");
}

fn decode_hex(value: &str) -> Vec<u8> {
    value
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}
